const buildUrlWithParams = (base: string, params?: Record<string, any>) => {
  const p = new URLSearchParams();
  Object.entries(params || {}).forEach(([k, v]) => { if (v !== undefined) p.append(k, String(v)); });
  const s = p.toString();
  return s ? `${base}?${s}` : base;
};

